ha-card {
  padding: 24px 28px;
  background: radial-gradient(ellipse at top right, rgba(215,178,109,0.18), transparent 60%), var(--card-background-color);
  border-radius: 22px;
}
ha-card h1 { font-size: 64px; font-weight: 800; letter-spacing: -0.04em; line-height: 1; margin: 0 0 14px 0; font-variant-numeric: tabular-nums; }
ha-card h1 span { font-size: 22px; font-weight: 400; color: var(--secondary-text-color); letter-spacing: 0; vertical-align: top; margin-left: 4px; }
ha-card p { color: var(--secondary-text-color); font-size: 13px; margin: 0; line-height: 1.6; }
ha-card p strong:first-child { color: var(--secondary-text-color); letter-spacing: 0.16em; font-weight: 800; margin-right: 8px; }

ha-card { aspect-ratio: 1 / 1; border-radius: 50% !important; padding: 0 !important; min-height: 0 !important; max-width: 56px; margin: 0 auto; }
ha-tile-info { display: none !important; }
.container { padding: 0 !important; height: 100%; }
.tile { padding: 0 !important; height: 100%; display: flex; align-items: center; justify-content: center; }
ha-tile-icon { --tile-icon-size: 100%; margin: 0 !important; }

