ha-card {
  padding: 16px 18px 14px 18px;
  border-radius: 14px;
  position: relative;
  overflow: hidden;
  min-height: 130px;
}
ha-card p:first-child { font-size: 11px; text-transform: uppercase; letter-spacing: 0.16em; color: var(--secondary-text-color); font-weight: 800; margin: 0 0 8px 0; }
ha-card p:first-child strong { color: var(--primary-text-color); white-space: nowrap; }
ha-card h1 { font-size: 32px; font-weight: 800; margin: 0 0 6px 0; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; line-height: 1; }
ha-card p:last-child { color: var(--secondary-text-color); font-size: 12px; margin: 0 0 12px 0; }
ha-card::after {
  content: "";
  position: absolute; left: 18px; right: 18px; bottom: 12px;
  display: block;
  height: 6px;
  border-radius: 999px;
  background: linear-gradient(to right, var(--info-color) 0%, var(--info-color) {{ ((states('sensor.sonoff_snzb_02d_temperature') | float(0) / 26 * 100) | round(0)) }}%, rgba(255,255,255,0.06) {{ ((states('sensor.sonoff_snzb_02d_temperature') | float(0) / 26 * 100) | round(0)) }}%, rgba(255,255,255,0.06) 100%);
}

